class NotEnoughParametersProvided(Exception):
    """ When no rf_attenuator is provided to work on."""


class TooManyParametersProvided(Exception):
    """ Provided both rf_attenuator object and named parameters. """


class AttenuatorTypeNotSupported(Exception):
    pass


class AttenuationDifferentThanExpected(Exception):
    pass


class AttenuationOutOfBounds(Exception):
    def __init__(self, src_att_string, att_val, min_val, max_val):
        self.src_att_string = src_att_string
        self.att_val = att_val
        self.min_val = min_val
        self.max_val = max_val
        msgp = "Given value {} dB is out of range [{} dB, {} dB]. Given value string: {}"
        msg = msgp.format(att_val, min_val, max_val, src_att_string)
        super(AttenuationOutOfBounds, self).__init__(msg)


class AttenuationReadError(Exception):
    pass


class AttenuationSetError(Exception):
    pass


class AttenuatorCmdError(Exception):
    pass


class AttenuatorInitiationFailed(Exception):
    pass


class InvalidUnit(Exception):
    pass


class MultiPortsNotSupported(Exception):
    pass


class AttenuationValueIsOtherThanExpected(Exception):
    """
    For backwards compatibility in test repos. Must be replaced with `AttenuationDifferentThanExpected`
    """


class PortDoesNotExist(Exception):
    """
    For backwards compatibility in test repos. Now must be replaced with
    `AttenuationReadError` or `AttenuationSetError`
    """


class UnitInvalid(Exception):
    """
    For backwards compatibility in test repos. Now must be replaced with `InvalidUnit`
    """
